#include <iostream>
#include <utility>
#include <string>

template<class T>
class Box {
public:
    explicit Box(T value) : value_(std::move(value)) {}
    const T& value() const { return value_; }
private: T value_;
};
int main() { Box<std::string> box{"leaf"}; std::cout << box.value() << '\n'; }
